-- ============================================================================
-- Database MySQL: telkom_dashboard (Menu Kuadran SJT)
-- Host: 127.0.0.1 | Port: 3306 | User: root | Password: (kosong)
-- ============================================================================
CREATE DATABASE IF NOT EXISTS `telkom_dashboard` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `telkom_dashboard`;

CREATE TABLE IF NOT EXISTS `kuadran_summaries` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `bulan` VARCHAR(10) NOT NULL COMMENT 'Jul, Aug, Sep, Oct, Nov, Dec',
  `period` VARCHAR(10) NOT NULL DEFAULT '' COMMENT 'YYYYMM, contoh: 202607, 202608',
  `telda` VARCHAR(100) NOT NULL COMMENT 'Region / Telda',
  `unit` VARCHAR(50) NOT NULL COMMENT 'Segment: Business, Enterprise, Government',
  `kw_awal` VARCHAR(10) NOT NULL DEFAULT '' COMMENT '1..4, NEW, atau kosong untuk bulan dasar',
  `kw_akhir` TINYINT UNSIGNED NOT NULL COMMENT 'Kuadran bulan berjalan (1..4)',
  `jumlah` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Jumlah pelanggan',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_kuadran_summary` (`bulan`, `telda`, `unit`, `kw_awal`, `kw_akhir`),
  KEY `idx_bulan` (`bulan`),
  KEY `idx_telda` (`telda`),
  KEY `idx_unit` (`unit`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `kuadran_uploads` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `filename` VARCHAR(255) NOT NULL,
  `months` VARCHAR(100) NOT NULL,
  `row_count` INT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

TRUNCATE TABLE `kuadran_summaries`;

-- ============================================================================
-- Tabel MySQL untuk Menu: MoM & Support Needed
-- ============================================================================
CREATE TABLE IF NOT EXISTS `mom_action_plans` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `no` VARCHAR(20) NOT NULL DEFAULT '',
  `tgl` VARCHAR(30) NOT NULL DEFAULT '',
  `agenda` VARCHAR(120) NOT NULL DEFAULT 'FORUM WITEL',
  `main_topic` VARCHAR(255) NOT NULL DEFAULT '',
  `unit_telda` VARCHAR(100) NOT NULL DEFAULT 'PRQ',
  `peserta` TEXT NULL,
  `pembahasan` LONGTEXT NULL,
  `pembahasan_notulen` LONGTEXT NULL,
  `action_plan` TEXT NOT NULL,
  `uic` VARCHAR(150) NOT NULL DEFAULT 'PRQ',
  `destinasi_fu` VARCHAR(255) NOT NULL DEFAULT '-',
  `support_needed` TEXT NULL,
  `deadline` VARCHAR(80) NOT NULL DEFAULT '-',
  `status` VARCHAR(30) NOT NULL DEFAULT 'BELUM FU',
  `notes` TEXT NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_mom_agenda` (`agenda`),
  KEY `idx_mom_status` (`status`),
  KEY `idx_mom_uic` (`uic`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mom_uploads` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `filename` VARCHAR(255) NOT NULL,
  `sheet_name` VARCHAR(100) NOT NULL DEFAULT 'Notulensi Tracker',
  `row_count` INT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

TRUNCATE TABLE `mom_action_plans`;
